import json,subprocess,sys
S='<scratch>/'
for b,sets in R.items():
    key=json.load(open(S+b+'/key.json')); out={'anchors':{},'candidates':{}}
    for code,js in sets.items():
        k=key[code]
        for i,side in enumerate('AB'):
            vals=[j[i] for j in js]
            if k['anchor']: out['anchors'][k[side]]=vals
            else:
                sp=k['label'].split()[1]; tag='live' if k[side].endswith('-base.png') else 'c1024'
                out['candidates'][f'{sp} {tag}']=vals
    json.dump(out,open(S+b+'/batch.json','w'),indent=1)
    r=json.loads(subprocess.run(['python3','tools/visual_judge/calibrate.py',S+b+'/batch.json'],capture_output=True,text=True).stdout)
    open(S+b+'/mapped.json','w').write(json.dumps(r,indent=1))
    f=r['fit']; print(b,'slope',f['slope'],'int',f['intercept'],'rmse',r['anchor_rmse'],'confirm',r['confirming_batch'],r['warnings'])
    c=r['candidates']; sps=sorted({n.split()[0] for n in c})
    for sp in sps:
        L=c[sp+' live']['mapped_mean']; C=c[sp+' c1024']['mapped_mean']
        print(f'  {sp:18s} live {L:.2f}  cand {C:.2f}  {C-L:+.2f}', '*' if C>=6.7 and C>L else '')
